class Solution {
public:
    vector<vector<int>> primePairs(int n) {
        vector<bool> isp(n + 1, true);
        isp[0] = isp[1] = false;
        for (long long i = 2; i * i <= n; i++)
            if (isp[i])
                for (long long j = i * i; j <= n; j += i) isp[j] = false;
        vector<vector<int>> res;
        for (int x = 2; x <= n / 2; x++)
            if (isp[x] && isp[n - x]) res.push_back({x, n - x});
        return res;
    }
};

