class Solution {
    public List<List<Integer>> primePairs(int n) {
        boolean[] isp = new boolean[n + 1];
        Arrays.fill(isp, true);
        if (n >= 0) isp[0] = false;
        if (n >= 1) isp[1] = false;
        for (int i = 2; (long) i * i <= n; i++)
            if (isp[i])
                for (long j = (long) i * i; j <= n; j += i) isp[(int) j] = false;
        List<List<Integer>> res = new ArrayList<>();
        for (int x = 2; x <= n / 2; x++)
            if (isp[x] && isp[n - x]) res.add(Arrays.asList(x, n - x));
        return res;
    }
}

