class Solution:
    def primePairs(self, n: int) -> List[List[int]]:
        def isp(v):
            if v < 2: return False
            i = 2
            while i * i <= v:
                if v % i == 0: return False
                i += 1
            return True
        return [[x, n - x] for x in range(2, n // 2 + 1) if isp(x) and isp(n - x)]

